schema_ddl:
CREATE TABLE polizze (
    id SERIAL PRIMARY KEY,
    numero_polizza TEXT NOT NULL UNIQUE,
    data_emissione DATE NOT NULL,
    data_scadenza DATE NOT NULL CHECK (data_scadenza >= data_emissione),
    premio NUMERIC(10,2) NOT NULL CHECK (premio >= 0),
    importo_assicurato NUMERIC(12,2) NOT NULL CHECK (importo_assicurato >= 0),
    polizza_padre_id INT NULL REFERENCES polizze(id)
);

COMMENT ON TABLE polizze IS 'Rappresenta le polizze assicurative con relazioni gerarchiche ricorsieve.';
COMMENT ON COLUMN polizze.polizza_padre_id IS 'Identificativo della polizza genitore per tracciare relazioni gerarchiche o di rete.';
